def build_export_plan(request: dict, policy: dict):
    public_fields = {str(item) for item in policy.get('public_fields', [])}
    default_fields = [str(item) for item in policy.get('default_fields', [])]
    fields = {item for item in default_fields if item in public_fields}
    if request.get('preview') is True:
        fields.update(str(item) for item in policy.get('diagnostic_fields', []))
    return {'fields': sorted(fields), 'preview': bool(request.get('preview', False))}
